-- Kluby ČSV (zdroj evidence.vzpirani.cz, 2026-11-20). Generováno: npm run update:clubs
on conflict (id) do update set name = excluded.name, region = excluded.region, city = excluded.city,
  address = excluded.address, lat = excluded.lat, lng = excluded.lng, web = excluded.web,
  facebook = excluded.facebook, instagram = excluded.instagram;
